import os, time, requests

BASE = "https://cc.example.com"
USER, PASSWORD = os.environ["CC_USER"], os.environ["CC_PASSWORD"]

session = requests.Session()
session.verify = "lab-ca.pem"                 # trust the lab CA, never verify=False

def login():
    r = session.post(f"{BASE}/dna/system/api/v1/auth/token",
                     auth=(USER, PASSWORD), timeout=10)
    r.raise_for_status()
    session.headers["X-Auth-Token"] = r.json()["Token"]

def api_get(path, renewed=False):
    r = session.get(f"{BASE}{path}", timeout=30)
    if r.status_code == 200:
        return r.json()
    if r.status_code == 401 and not renewed:  # expired token: renew once
        login()
        return api_get(path, renewed=True)
    if r.status_code == 403:
        raise PermissionError("role lacks permission for " + path)
    if r.status_code == 429:
        time.sleep(int(r.headers.get("Retry-After", 5)))
        return api_get(path, renewed)
    r.raise_for_status()                      # 4xx/5xx: stop with details

login()
devices = api_get("/dna/intent/api/v1/network-device")["response"]
print(len(devices), "devices")

